<?php
namespace App\Models; use App\Core\Model; class User extends Model{protected string $table='users'; public function byLogin(string $login):?array{$s=$this->db()->prepare('SELECT u.*,r.slug role FROM users u JOIN roles r ON r.id=u.role_id WHERE username=? OR mobile=? LIMIT 1');$s->execute([$login,$login]);return $s->fetch()?:null;} public function create(array $d):int{$s=$this->db()->prepare('INSERT INTO users(role_id,first_name,last_name,national_code,mobile,username,password,status,address,card_number,account_number,iban) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$d['role_id'],$d['first_name'],$d['last_name'],$d['national_code'],$d['mobile'],$d['username'],password_hash($d['password'],PASSWORD_DEFAULT),$d['status']??'active',$d['address']??null,$d['card_number']??null,$d['account_number']??null,$d['iban']??null]);return (int)$this->db()->lastInsertId();}}
